/*
 © 2024-2026 Captain Compliance
 www.captaincompliance.com

 Consent-Mode-native GTM template:
 1. setDefaultConsentState (region-scoped, non-essential denied by default)
 2. injectScript the Captain Compliance banner (loads the CMP UI + geo/GPC)
 3. updateConsentState from the captainComplianceConsent event / cookie
*/

const log = require('logToConsole');
const injectScript = require('injectScript');
const encode = require('encodeUriComponent');
const makeInteger = require('makeInteger');
const JSON = require('JSON');
const getCookieValues = require('getCookieValues');
const copyFromDataLayer = require('copyFromDataLayer');
const addConsentListener = require('addConsentListener');
const setDefaultConsentState = require('setDefaultConsentState');
const updateConsentState = require('updateConsentState');
const gtmOnSuccess = data.gtmOnSuccess;
const gtmOnFailure = data.gtmOnFailure;

// ---- config ----------------------------------------------------------------
// GTM's sandboxed JS does not support regex literals, so trim trailing
// slashes with a small loop (a regex-based strip fails the sandbox import).
const baseUrl = (function (url) {
  while (url.charAt(url.length - 1) === '/') {
    url = url.substring(0, url.length - 1);
  }
  return url;
})(data.bannerBaseUrl || 'https://api-prod.cptn.co');
const eventName = data.dataLayerEventName || 'captainComplianceConsent';
const cookieName = data.consentCookieName || 'cc_consent_preference';
const enableConsentMode = data.enableConsentMode !== false;
const honorGpc = data.honorGpc !== false;

// Captain Compliance category -> Google Consent Mode v2 signals.
const AD_SIGNALS = ['ad_storage', 'ad_user_data', 'ad_personalization', 'personalization_storage'];
const ANALYTICS_SIGNALS = ['analytics_storage'];
const FUNCTIONALITY_SIGNALS = ['functionality_storage'];

// ---- 1. default consent state ---------------------------------------------
if (enableConsentMode) {
  const scope = data.consentScope || 'regions';
  const waitMs = makeInteger(data.waitForUpdate) || 500;

  // Non-essential storage denied; essential (security) always granted.
  const deniedDefault = {
    ad_storage: 'denied',
    ad_user_data: 'denied',
    ad_personalization: 'denied',
    analytics_storage: 'denied',
    functionality_storage: 'denied',
    personalization_storage: 'denied',
    security_storage: 'granted',
    wait_for_update: waitMs
  };
  const grantedDefault = {
    ad_storage: 'granted',
    ad_user_data: 'granted',
    ad_personalization: 'granted',
    analytics_storage: 'granted',
    functionality_storage: 'granted',
    personalization_storage: 'granted',
    security_storage: 'granted'
  };

  if (scope === 'global_optout') {
    // Allow everywhere until the visitor opts out (US-style).
    setDefaultConsentState(grantedDefault);
  } else if (scope === 'global_optin') {
    // Deny non-essential everywhere until the visitor consents.
    setDefaultConsentState(deniedDefault);
  } else {
    // Specific regions: deny in the listed regions, allow elsewhere.
    let regions = [];
    if (data.requiredRegions) {
      regions = data.requiredRegions.split(',').map(function (r) {
        return r.trim();
      }).filter(function (r) {
        return r.length > 0;
      });
    }
    if (regions.length === 0) {
      // Region mode with no regions listed: fall back to deny everywhere.
      setDefaultConsentState(deniedDefault);
    } else {
      deniedDefault.region = regions;
      setDefaultConsentState(deniedDefault);
      // Everything outside the listed regions is granted (opt-out). The
      // region-scoped denied default above wins inside the listed regions.
      setDefaultConsentState(grantedDefault);
    }
  }

  if (data.adsDataRedaction) {
    // Signalled to Google tags via gtag; exposed for completeness.
    log('[CaptainCompliance] ads_data_redaction requested (configure on the Google tag).');
  }
  if (data.urlPassthrough) {
    log('[CaptainCompliance] url_passthrough requested (configure on the Google tag).');
  }
}

// ---- consent mapping helpers ----------------------------------------------
function applyGrant(signals, state, granted) {
  for (let i = 0; i < signals.length; i++) {
    state[signals[i]] = granted ? 'granted' : 'denied';
  }
}

// Read consent from the dataLayer event payload, falling back to the cookie.
function readSelectedCookies(eventData) {
  if (eventData && eventData.selectedCookies) {
    return eventData.selectedCookies;
  }
  const raw = getCookieValues(cookieName);
  if (raw && raw.length) {
    const parsed = JSON.parse(raw[0]);
    if (parsed && parsed.selectedCookies) {
      return parsed.selectedCookies;
    }
  }
  return null;
}

function readGpc(eventData) {
  if (eventData && (eventData.gpc === true || eventData.globalPrivacyControl === true)) {
    return true;
  }
  const raw = getCookieValues(cookieName);
  if (raw && raw.length) {
    const parsed = JSON.parse(raw[0]);
    if (parsed && (parsed.gpc === true || parsed.globalPrivacyControl === true)) {
      return true;
    }
  }
  return false;
}

function pushUpdate(eventData) {
  if (!enableConsentMode) return;
  const selected = readSelectedCookies(eventData);
  if (!selected) return;

  const perf = selected.PERFORMANCE_COOKIES === true;
  let targeting = selected.TARGETING_COOKIES === true;
  const functionality = selected.FUNCTIONALITY_COOKIES === true;

  // Honor GPC: force ad/analytics purposes denied when a GPC signal is present.
  const gpc = honorGpc && readGpc(eventData);

  const update = { security_storage: 'granted' };
  applyGrant(ANALYTICS_SIGNALS, update, perf && !gpc);
  applyGrant(AD_SIGNALS, update, targeting && !gpc);
  applyGrant(FUNCTIONALITY_SIGNALS, update, functionality);

  updateConsentState(update);
  log('[CaptainCompliance] updateConsentState', update);
}

// ---- 3. update consent on banner event / listener -------------------------
if (enableConsentMode) {
  // Fire once for consent that already exists at container load.
  const existing = copyFromDataLayer(eventName);
  if (existing) {
    pushUpdate(existing);
  } else {
    pushUpdate(null); // try the cookie
  }

  // React to later consent changes pushed by the banner.
  addConsentListener('ad_storage', function () {
    pushUpdate(copyFromDataLayer(eventName));
  });
}

// ---- 2. inject the Captain Compliance banner (loads early) ----------------
const bannerUrl = baseUrl + '/banner/script?accessToken=' + encode(data.accessToken);
injectScript(bannerUrl, gtmOnSuccess, gtmOnFailure, 'ccBanner');


